2	// passer la souris vers la caméra, seuls ses enfants la captent. Sous le rideau de transition
3	// (SpaceTransitionOverlay, z-index 30) et sous la barre d'aide de TopRightMenu (z-index 1000).
4	.container {
5	  position: absolute;
6	  inset: 0;
7	  z-index: 15;
8	  pointer-events: none;
9	
10	  > * {
11	    pointer-events: auto;
12	  }
13	}
