// (SpaceTransitionOverlay, z-index 30) et sous la barre d'aide de TopRightMenu (z-index 1000).
.container {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;

  > * {
    pointer-events: auto;
  }
}

