1	import { useEffect, useRef, useState } from 'react';
2	import { showError, showSuccess, showWarning } from '@/utils/toast';
3	import {
4	  parseGCode,
5	  stateAt,
6	  timeAtIndex,
7	  indexAtTime,
8	  SUSPICIOUS_C_RANGE_DEG,
9	  type ParsedGCode,
10	} from '@/components/gcodeLayer';
11	
12	/**
13	 * Logique de l'espace Prévisualisation, sans interface : chargement de fichier G-code (dépôt sur
14	 * la fenêtre ou sélecteur), horloge de lecture et affichage des trajets à vide. Le rendu 3D est
15	 * fait par Viewport3D, piloté par les événements :
16	 *  - `apex-gcode-loaded` { parsed } : nouvelle trajectoire à afficher ;
17	 *  - `apex-gcode-time` { t } : position de lecture (index de mouvement fractionnaire) ;
18	 *  - `apex-gcode-show-travel` { show } : affichage des trajets à vide.
19	 */
20	
21	// Multiplicateurs du temps machine réel (1 = vitesse d'impression réelle, avances F du fichier).
22	export const GCODE_SPEED_OPTIONS = [0.01, 1, 4, 16, 64, 256];
23	export const GCODE_ACCEPT = '.gcode,.gco,.g,.ngc';
24	/** Reconnaît un nom de fichier G-code par son extension — exporté pour Sidebar.tsx (bascule
25	 * automatique vers l'espace Prévisualisation au dépôt d'un tel fichier en Préparation). */
26	export const GCODE_FILE_EXT = /\.(gcode|gco|g|ngc)$/i;
27	
28	export interface GCodeFileInfo {
29	  name: string;
30	  moves: number;
31	  extruding: number;
32	  minZ: number;
33	  maxZ: number;
34	  minC: number;
35	  maxC: number;
36	}
37	
38	const dispatchTime = (t: number) =>
39	  window.dispatchEvent(new CustomEvent('apex-gcode-time', { detail: { t } }));
40	
41	/** @param active Espace Prévisualisation affiché (active le dépôt de fichier, coupe la lecture sinon). */
42	export function useGCodePreview(active: boolean) {
43	  const parsedRef = useRef<ParsedGCode | null>(null);
44	  const tRef = useRef(0);
45	  const dragDepthRef = useRef(0);
46	
47	  const [fileInfo, setFileInfo] = useState<GCodeFileInfo | null>(null);
48	  const [t, setT] = useState(0);
49	  const [isPlaying, setIsPlaying] = useState(false);
50	  const [speed, setSpeed] = useState(GCODE_SPEED_OPTIONS[1]);
51	  const [showTravel, setShowTravel] = useState(false);
52	  const [showFullHead, setShowFullHead] = useState(true);
53	  const [isDragging, setIsDragging] = useState(false);
54	  // Le temps de lire le fichier et de parser son texte (`loadFile`, ci-dessous) : permet à
55	  // GCodePreviewBar de s'afficher dès le début du chargement plutôt que d'attendre `fileInfo`.
56	  const [isLoading, setIsLoading] = useState(false);
57	
58	  useEffect(() => {
59	    if (!active) setIsPlaying(false);
60	  }, [active]);
61	
62	  useEffect(() => {
63	    window.dispatchEvent(new CustomEvent('apex-gcode-show-travel', { detail: { show: showTravel } }));
64	  }, [showTravel]);
65	
66	  useEffect(() => {
67	    window.dispatchEvent(new CustomEvent('apex-gcode-show-full-head', { detail: { show: showFullHead } }));
68	  }, [showFullHead]);
69	
70	  // Horloge de lecture : avance le temps machine (durées réelles des mouvements, cf.
71	  // `ParsedGCode.times`) à `speed` × le temps réel, le reconvertit en index de mouvement `t`,
72	  // pousse chaque image au viewport et rafraîchit l'état React à ~20 Hz seulement.
73	  useEffect(() => {
74	    if (!isPlaying) return;
75	    const parsed = parsedRef.current;
76	    if (!parsed) return;
77	    const last = parsed.moves.length - 1;
78	    let raf = 0;
79	    let prev = performance.now();
80	    let sinceUiSync = 0;
81	    const step = (now: number) => {
82	      const dt = (now - prev) / 1000;
83	      prev = now;
84	      const s = timeAtIndex(parsed.times, tRef.current) + speed * dt;
85	      tRef.current = Math.min(last, indexAtTime(parsed.times, s));
86	      dispatchTime(tRef.current);
87	      sinceUiSync += dt;
88	      if (tRef.current >= last) {
89	        setT(last);
90	        setIsPlaying(false);
91	        return;
92	      }
93	      if (sinceUiSync > 1 / 20) {
94	        sinceUiSync = 0;
95	        setT(tRef.current);
96	      }
97	      raf = requestAnimationFrame(step);
98	    };
99	    raf = requestAnimationFrame(step);
100	    return () => cancelAnimationFrame(raf);
101	  }, [isPlaying, speed]);
102	
103	  const loadFile = async (file: File) => {
104	    if (!GCODE_FILE_EXT.test(file.name)) {
105	      showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
106	      return;
107	    }
108	    setIsLoading(true);
109	    let parsed: ParsedGCode;
110	    try {
111	      parsed = parseGCode(await file.text());
112	    } catch {
113	      showError('Impossible de lire ce fichier G-code.');
114	      setIsLoading(false);
115	      return;
116	    }
117	    if (parsed.moves.length < 2) {
118	      showError('Aucune trajectoire G00 exploitable dans ce fichier.');
119	      setIsLoading(false);
120	      return;
121	    }
122	
123	    parsedRef.current = parsed;
124	    const last = parsed.moves.length - 1;
125	    tRef.current = last;
126	    setIsPlaying(false);
127	    setT(last);
128	    window.dispatchEvent(new CustomEvent('apex-gcode-loaded', { detail: { parsed } }));
129	
130	    setFileInfo({
131	      name: file.name,
132	      moves: parsed.moves.length,
133	      extruding: parsed.extrudingCount,
134	      minZ: parsed.minZ,
135	      maxZ: parsed.maxZ,
136	      minC: parsed.minC,
137	      maxC: parsed.maxC,
138	    });
139	    setIsLoading(false);
140	
141	    if (parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
142	      showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
143	    } else {
144	      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
145	    }
146	  };
147	
148	  // Fichier reçu de Sidebar.tsx (dépôt en Préparation, cf. `enterPreview`) une fois la bascule
149	  // animée vers l'espace Prévisualisation terminée — dispatché seulement APRÈS
150	  // `apex-preview-toggled { active: true }`, donc toujours reçu ici avec `active` déjà vrai.
151	  // `loadFileRef` : la fonction est recréée à chaque rendu (elle ferme sur `file`, capturé par
152	  // paramètre, pas par un état qui changerait), mais l'effet ne doit s'abonner qu'une fois — sans
153	  // quoi il se désabonnerait/réabonnerait à chaque rendu de ce hook, coûteux pour rien puisque
154	  // seuls des setters stables (jamais lus depuis une valeur figée) sont appelés à l'intérieur.
155	  const loadFileRef = useRef(loadFile);
156	  loadFileRef.current = loadFile;
157	  useEffect(() => {
158	    const onEnteringPreviewWithFile = (e: Event) => {
159	      const file = (e as CustomEvent<{ file: File }>).detail?.file;
160	      if (file) loadFileRef.current(file);
161	    };
162	    window.addEventListener('apex-entering-preview-with-file', onEnteringPreviewWithFile);
163	    return () => window.removeEventListener('apex-entering-preview-with-file', onEnteringPreviewWithFile);
164	  }, []);
165	
166	  /** Ouvre le sélecteur de fichier système (sans élément `<input>` dans l'interface). */
167	  const openFilePicker = () => {
168	    const input = document.createElement('input');
169	    input.type = 'file';
170	    input.accept = GCODE_ACCEPT;
171	    input.onchange = () => {
172	      const file = input.files?.[0];
173	      if (file) loadFile(file);
174	    };
175	    input.click();
176	  };
177	
178	  // Dépôt de fichier sur toute la fenêtre tant que l'espace est affiché : le viewport garde la
179	  // souris pour la caméra, aucun élément d'interface n'a donc besoin de capter le dépôt.
180	  useEffect(() => {
181	    if (!active) return;
182	    const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
183	    const onDragEnter = (e: DragEvent) => {
184	      if (!hasFiles(e)) return;
185	      e.preventDefault();
186	      dragDepthRef.current++;
187	      setIsDragging(true);
188	    };
189	    const onDragOver = (e: DragEvent) => {
190	      if (!hasFiles(e)) return;
191	      e.preventDefault();
192	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
193	    };
194	    // Compteur : `dragleave` se déclenche aussi en passant d'un élément à un de ses enfants.
195	    const onDragLeave = (e: DragEvent) => {
196	      if (!hasFiles(e)) return;
197	      dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
198	      if (dragDepthRef.current === 0) setIsDragging(false);
199	    };
200	    const onDrop = (e: DragEvent) => {
201	      if (!hasFiles(e)) return;
202	      e.preventDefault();
203	      dragDepthRef.current = 0;
204	      setIsDragging(false);
205	      const file = e.dataTransfer?.files?.[0];
206	      if (file) loadFile(file);
207	    };
208	    window.addEventListener('dragenter', onDragEnter);
209	    window.addEventListener('dragover', onDragOver);
210	    window.addEventListener('dragleave', onDragLeave);
211	    window.addEventListener('drop', onDrop);
212	    return () => {
213	      window.removeEventListener('dragenter', onDragEnter);
214	      window.removeEventListener('dragover', onDragOver);
215	      window.removeEventListener('dragleave', onDragLeave);
216	      window.removeEventListener('drop', onDrop);
217	      dragDepthRef.current = 0;
218	      setIsDragging(false);
219	    };
220	  }, [active]);
221	
222	  /** Place la lecture sur l'index de mouvement `value` (fractionnaire) et met la lecture en pause. */
223	  const seek = (value: number) => {
224	    setIsPlaying(false);
225	    tRef.current = value;
226	    setT(value);
227	    dispatchTime(value);
228	  };
229	
230	  /** Lecture/pause ; repart du début si la lecture est au bout. */
231	  const togglePlay = () => {
232	    const parsed = parsedRef.current;
233	    if (!parsed) return;
234	    if (!isPlaying && tRef.current >= parsed.moves.length - 1) seek(0);
235	    setIsPlaying(!isPlaying);
236	  };
237	
238	  const parsed = parsedRef.current;
239	  /** État machine interpolé (r, c, z, b) à la position de lecture. */
240	  const current = parsed ? stateAt(parsed.moves, t) : null;
241	  /** Mouvement en cours d'exécution (pour savoir s'il extrude). */
242	  const currentMove = parsed ? parsed.moves[Math.min(parsed.moves.length - 1, Math.ceil(t))] : null;
243	  const lastIndex = fileInfo ? fileInfo.moves - 1 : 0;
244	
245	  return {
246	    fileInfo,
247	    t,
248	    lastIndex,
249	    current,
250	    currentMove,
251	    isPlaying,
252	    togglePlay,
253	    seek,
254	    speed,
255	    setSpeed,
256	    showTravel,
257	    setShowTravel,
258	    showFullHead,
259	    setShowFullHead,
260	    isDragging,
261	    isLoading,
262	    loadFile,
263	    openFilePicker,
264	  };
265	}
266

