1	import * as BABYLON from 'babylonjs';
2	import 'babylonjs-loaders';
3	import headModelUrl from '@/assets/models/aetheris-4.glb?url';
4	
5	/**
6	 * G-code polaire 4 axes de l'Apex : parseur + calque Babylon de prévisualisation.
7	 *
8	 * Ce n'est PAS un G-code cartésien de slicer classique : une seule commande de déplacement,
9	 * `G00 Y<C> X<R> Z<Z> B<B> [E<e>] F<f>`.
10	 *  - X = R : rayon depuis le centre du plateau (mm, ≥ 0).
11	 *  - Y = C : angle du plateau (degrés, absolu, JAMAIS replié modulo 360 — le générateur garde
12	 *    la continuité angulaire, un C > 360 ou négatif est normal).
13	 *  - Z : hauteur (mm). B : inclinaison de la tête vers +R (à l'opposé de l'axe de rotation), en
14	 *    degrés.
15	 *  - E (optionnel) : position absolue de l'extrudeur. E croissant = dépôt ; E absent ou
16	 *    stationnaire = trajet à vide.
17	 *
18	 * Représentation (cf. `createGCodeLayer`) :
19	 *  - La matière est stockée une fois pour toutes en repère plateau (x = R cos C, z = R sin C,
20	 *    avec le C du moment du dépôt) sous un noeud dont la rotation suit le C courant : plateau
21	 *    et matière tournent strictement ensemble.
22	 *  - La matière est un cordon (tube à section elliptique, cf. `buildBeadMesh`) orienté selon
23	 *    l'axe de buse du moment du dépôt ; les trajets à vide restent de simples lignes.
24	 *  - La tête reste dans le demi-plan machine fixe (R, 0, Z) ; c'est le plateau qui tourne pour
25	 *    amener la pièce sous elle.
26	 *  - R/Z sont les positions machine du PIVOT de l'axe B, pas de la buse : la pointe de buse est
27	 *    à NOZZLE_PIVOT_MM sous le pivot, le long de l'axe de la tête (cf. `nozzleTip`). Tête et
28	 *    matière déposée sont affichées à la pointe de buse ; l'état machine exposé (`stateAt`)
29	 *    reste en coordonnées pivot.
30	 *  - Tout est interpolé dans l'espace (R, C, Z, B) du firmware, jamais en cartésien : les
31	 *    segments sont subdivisés en angle pour suivre l'arc réellement parcouru, et la position
32	 *    animée entre deux consignes est interpolée en (R, C, Z, B) puis convertie.
33	 *  - Aucune décimation "1 point sur N" (sauts angulaires visibles sur les portions courbes).
34	 */
35	
36	export interface GCodeMove {
37	  r: number;
38	  c: number;
39	  z: number;
40	  b: number;
41	  extruding: boolean;
42	}
43	
44	export interface ParsedGCode {
45	  moves: GCodeMove[];
46	  /** Temps machine cumulé (s) à l'arrivée de chaque mouvement (`times[0] = 0`), déduit de la
47	   * distance parcourue par la buse et de l'avance F — cf. `timeAtIndex`/`indexAtTime`. */
48	  times: Float64Array;
49	  minZ: number;
50	  maxZ: number;
51	  maxR: number;
52	  minC: number;
53	  maxC: number;
54	  extrudingCount: number;
55	}
56	
57	const DEG2RAD = Math.PI / 180;
58	// Pas angulaire max d'un sous-segment : au-delà, la corde cartésienne s'écarte visiblement de
59	// l'arc réellement décrit par le firmware (qui interpole en C, pas en x/y).
60	const MAX_SUBSEGMENT_DEG = 0.5;
61	/** Au-delà de cette amplitude totale de C, le fichier vient très probablement de la version
62	 * boguée du générateur (C qui dérive de tour en tour au lieu d'osciller dans une plage étroite). */
63	export const SUSPICIOUS_C_RANGE_DEG = 720;
64	
65	/** Distance entre la pointe de buse et le pivot de l'axe B (mm), le long de l'axe de la tête. */
66	export const NOZZLE_PIVOT_MM = 46;
67	
68	/**
69	 * Pointe de buse (rayon, hauteur) dans le demi-plan machine, depuis la position du pivot (R, Z)
70	 * et l'inclinaison B (radians). La tête penche vers +R (cf. `headDir` dans `apply`), donc la
71	 * buse, SOUS le pivot, part vers −R. Z est calé pour que tête droite (B = 0) la buse soit
72	 * exactement à Z : seul l'écart dû à l'inclinaison, L·(1 − cos B), s'ajoute en hauteur.
73	 */
74	function nozzleTip(r: number, z: number, bRad: number, out: { r: number; z: number }) {
75	  out.r = r - NOZZLE_PIVOT_MM * Math.sin(bRad);
76	  out.z = z + NOZZLE_PIVOT_MM * (1 - Math.cos(bRad));
77	  return out;
78	}
79	
80	/** Avance (mm/min) supposée tant que le fichier n'a pas encore donné de F. */
81	const DEFAULT_FEED_MM_MIN = 1500;
82	/** Durée plancher d'un mouvement (s) : un mouvement quasi immobile pour la buse (rotation autour
83	 * du centre, consigne répétée) prend tout de même un instant. */
84	const MIN_MOVE_S = 1e-3;
85	
86	const G00_RE = /^G0*0(?![0-9])/i;
87	const WORD_RE = /([XYZBEF])\s*([-+]?(?:\d+\.?\d*|\.\d+))/gi;
88	
89	export function parseGCode(text: string): ParsedGCode {
90	  const moves: GCodeMove[] = [];
91	  const feeds: number[] = [];
92	  let r = 0, c = 0, z = 0, b = 0;
93	  let feed = DEFAULT_FEED_MM_MIN; // modal, comme le firmware
94	  let lastE: number | null = null;
95	  let extrudingCount = 0;
96	
97	  for (const rawLine of text.split(/\r?\n/)) {
98	    const line = rawLine.replace(/\(.*?\)/g, '').replace(/;.*$/, '').trim();
99	    if (!line || !G00_RE.test(line)) continue;
100	
101	    let e: number | null = null;
102	    WORD_RE.lastIndex = 0;
103	    let m: RegExpExecArray | null;
104	    while ((m = WORD_RE.exec(line)) !== null) {
105	      const value = parseFloat(m[2]);
106	      if (Number.isNaN(value)) continue;
107	      switch (m[1].toUpperCase()) {
108	        case 'X': r = value; break;
109	        case 'Y': c = value; break;
110	        case 'Z': z = value; break;
111	        case 'B': b = value; break;
112	        case 'E': e = value; break;
113	        case 'F': if (value > 0) feed = value; break;
114	      }
115	    }
116	
117	    const extruding = e !== null && lastE !== null && e > lastE + 1e-9;
118	    if (e !== null) lastE = e;
119	    if (extruding) extrudingCount++;
120	    moves.push({ r, c, z, b, extruding });
121	    feeds.push(feed);
122	  }
123	
124	  // Durée de chaque mouvement : distance parcourue par la pointe de buse RELATIVEMENT au plateau
125	  // (ΔR, ΔZ de la pointe et arc r·ΔC dû à la rotation du plateau) à l'avance F du mouvement.
126	  // Sans ça, la lecture avancerait d'un nombre fixe de mouvements par seconde : une longue ligne
127	  // droite serait franchie aussi vite qu'un segment de 0,1 mm — la tête « se téléporterait ».
128	  const times = new Float64Array(moves.length);
129	  const tipA = { r: 0, z: 0 };
130	  const tipB = { r: 0, z: 0 };
131	  for (let k = 1; k < moves.length; k++) {
132	    const a = moves[k - 1];
133	    const m = moves[k];
134	    nozzleTip(a.r, a.z, a.b * DEG2RAD, tipA);
135	    nozzleTip(m.r, m.z, m.b * DEG2RAD, tipB);
136	    const dr = tipB.r - tipA.r;
137	    const dz = tipB.z - tipA.z;
138	    const arc = ((Math.abs(tipA.r) + Math.abs(tipB.r)) / 2) * (m.c - a.c) * DEG2RAD;
139	    const dist = Math.sqrt(dr * dr + dz * dz + arc * arc);
140	    times[k] = times[k - 1] + Math.max(MIN_MOVE_S, dist / (feeds[k] / 60));
141	  }
142	
143	  // Bornes en Z/R de la pointe de buse (ce qui est affiché), pas du pivot.
144	  let minZ = Infinity, maxZ = -Infinity, maxR = 0, minC = Infinity, maxC = -Infinity;
145	  const tip = { r: 0, z: 0 };
146	  for (const mv of moves) {
147	    nozzleTip(mv.r, mv.z, mv.b * DEG2RAD, tip);
148	    if (tip.z < minZ) minZ = tip.z;
149	    if (tip.z > maxZ) maxZ = tip.z;
150	    if (Math.abs(tip.r) > maxR) maxR = Math.abs(tip.r);
151	    if (mv.c < minC) minC = mv.c;
152	    if (mv.c > maxC) maxC = mv.c;
153	  }
154	  if (!moves.length) { minZ = maxZ = minC = maxC = 0; }
155	
156	  return { moves, times, minZ, maxZ, maxR, minC, maxC, extrudingCount };
157	}
158	
159	/** Temps machine (s) à l'index de mouvement fractionnaire `t`. */
160	export function timeAtIndex(times: Float64Array, t: number) {
161	  const last = times.length - 1;
162	  const i = Math.max(0, Math.min(last, Math.floor(t)));
163	  if (i >= last) return times[last];
164	  return times[i] + (times[i + 1] - times[i]) * (t - i);
165	}
166	
167	/** Index de mouvement fractionnaire atteint au temps machine `s` (inverse de `timeAtIndex`). */
168	export function indexAtTime(times: Float64Array, s: number) {
169	  const last = times.length - 1;
170	  if (s <= 0) return 0;
171	  if (s >= times[last]) return last;
172	  let lo = 0, hi = last; // times[lo] <= s < times[hi]
173	  while (hi - lo > 1) {
174	    const mid = (lo + hi) >> 1;
175	    if (times[mid] <= s) lo = mid; else hi = mid;
176	  }
177	  return lo + (s - times[lo]) / (times[hi] - times[lo]);
178	}
179	
180	/** Position (R, C, Z, B) interpolée linéairement — comme le firmware — au temps `t` exprimé
181	 * en index de mouvement fractionnaire. */
182	export function stateAt(moves: GCodeMove[], t: number) {
183	  const i = Math.max(0, Math.min(moves.length - 1, Math.floor(t)));
184	  const a = moves[i];
185	  const b = moves[Math.min(moves.length - 1, i + 1)];
186	  const f = Math.max(0, Math.min(1, t - i));
187	  return {
188	    r: a.r + (b.r - a.r) * f,
189	    c: a.c + (b.c - a.c) * f,
190	    z: a.z + (b.z - a.z) * f,
191	    b: a.b + (b.b - a.b) * f,
192	  };
193	}
194	
195	interface PathMesh {
196	  mesh: BABYLON.Mesh | null;
197	  /** Nombre d'indices à dessiner une fois le mouvement k terminé. */
198	  cumIndices: Uint32Array;
199	  /** Nombre d'indices par sous-segment : granularité de l'affichage d'un mouvement partiel. */
200	  indicesPerStep: number;
201	}
202	
203	/** Section du cordon déposé (mm) : largeur de part et d'autre de la trajectoire, et épaisseur le
204	 * long de l'axe de la buse. Pas d'information de largeur/couche dans ce G-code : valeurs
205	 * nominales. */
206	export const BEAD_WIDTH_MM = 0.6;
207	export const BEAD_HEIGHT_MM = 0.3;
208	/** Nombre de facettes de la section du cordon. */
209	const TUBE_SIDES = 6;
210	
211	/** Donne à un sous-maillage affiché par préfixe (`indexCount`) une boîte englobante propre. */
212	function finalizePathMesh(mesh: BABYLON.Mesh) {
213	  // Tant que `indexCount` couvre toute la géométrie, Babylon traite le sous-maillage comme
214	  // « global » et lui prête la boîte englobante du maillage ; dès qu'on n'en affiche qu'un
215	  // préfixe, il lit sa boîte propre — jamais créée, d'où un crash dans le tri des objets
216	  // transparents qui arrêtait la boucle de rendu. On lui en donne une une fois pour toutes :
217	  // celle de la trajectoire complète, qui englobe n'importe quel préfixe (pas de
218	  // `refreshBoundingInfo`, qui reparcourrait les indices à chaque rotation du plateau).
219	  const { minimum, maximum } = mesh.getBoundingInfo();
220	  mesh.subMeshes[0].setBoundingInfo(new BABYLON.BoundingInfo(minimum.clone(), maximum.clone()));
221	  mesh.isPickable = false;
222	  mesh.alwaysSelectAsActiveMesh = true;
223	}
224	
225	/**
226	 * Construit le cordon de matière (repère plateau) : un tube à section elliptique le long de tous
227	 * les mouvements qui extrudent, dans l'ordre du fichier. La section est orientée selon l'axe de
228	 * la buse au moment du dépôt (écrasée le long de cet axe, BEAD_HEIGHT_MM) et centrée une
229	 * demi-épaisseur sous la pointe de buse, là où la matière est réellement posée. Les mouvements
230	 * extrudants consécutifs partagent leurs anneaux de jonction : un seul tube continu par suite
231	 * ininterrompue de dépôts. Comme pour les lignes, n'importe quel préfixe s'affiche en changeant
232	 * `indexCount`, sans reconstruire la géométrie.
233	 */
234	function buildBeadMesh(
235	  name: string,
236	  parsed: ParsedGCode,
237	  segments: Uint32Array,
238	  colorAt: (z: number, out: BABYLON.Color4) => void,
239	  material: BABYLON.Material,
240	  scene: BABYLON.Scene,
241	): PathMesh {
242	  const { moves } = parsed;
243	  const indicesPerStep = TUBE_SIDES * 6;
244	  const cumIndices = new Uint32Array(moves.length);
245	
246	  let capacity = 0;
247	  for (let k = 1; k < moves.length; k++) {
248	    if (moves[k].extruding) capacity += segments[k] + 1;
249	  }
250	  if (capacity === 0) return { mesh: null, cumIndices, indicesPerStep };
251	
252	  // Passe 1 : échantillons le long de la trajectoire — centre du cordon, axe de buse, mouvement
253	  // propriétaire et début de tube (pas de sous-segment qui le relie au précédent).
254	  const centers = new Float32Array(capacity * 3);
255	  const axes = new Float32Array(capacity * 3);
256	  const owner = new Uint32Array(capacity);
257	  const stripStart = new Uint8Array(capacity);
258	  const tip = { r: 0, z: 0 };
259	  const halfH = BEAD_HEIGHT_MM / 2;
260	  let count = 0;
261	
262	  for (let k = 1; k < moves.length; k++) {
263	    const cur = moves[k];
264	    if (!cur.extruding) continue;
265	    const prev = moves[k - 1];
266	    // Le mouvement précédent était déjà un dépôt dessiné : son dernier échantillon est notre
267	    // point de départ, on prolonge le même tube au lieu d'en ouvrir un nouveau.
268	    const continues = k > 1 && prev.extruding;
269	    const n = segments[k];
270	    for (let s = continues ? 1 : 0; s <= n; s++) {
271	      const f = s / n;
272	      const c = (prev.c + (cur.c - prev.c) * f) * DEG2RAD;
273	      const b = (prev.b + (cur.b - prev.b) * f) * DEG2RAD;
274	      nozzleTip(prev.r + (cur.r - prev.r) * f, prev.z + (cur.z - prev.z) * f, b, tip);
275	      const cosC = Math.cos(c), sinC = Math.sin(c);
276	      // Axe de buse (vers le haut de la tête) en repère plateau : (sin B, cos B) dans le
277	      // demi-plan machine, dont la direction radiale est à l'angle C du dépôt.
278	      const ax = Math.sin(b) * cosC, ay = Math.cos(b), az = Math.sin(b) * sinC;
279	      centers[count * 3] = tip.r * cosC - ax * halfH;
280	      centers[count * 3 + 1] = tip.z - ay * halfH;
281	      centers[count * 3 + 2] = tip.r * sinC - az * halfH;
282	      axes[count * 3] = ax;
283	      axes[count * 3 + 1] = ay;
284	      axes[count * 3 + 2] = az;
285	      owner[count] = k;
286	      stripStart[count] = s === 0 ? 1 : 0;
287	      count++;
288	    }
289	  }
290	
291	  // Passe 2 : un anneau elliptique par échantillon, dans le repère (côté, axe de buse)
292	  // perpendiculaire à la tangente, puis les quads entre anneaux consécutifs d'un même tube.
293	  const positions = new Float32Array(count * TUBE_SIDES * 3);
294	  const normals = new Float32Array(count * TUBE_SIDES * 3);
295	  const colors = new Float32Array(count * TUBE_SIDES * 4);
296	  const indices = new Uint32Array(count * indicesPerStep);
297	  const ringCos = new Float32Array(TUBE_SIDES);
298	  const ringSin = new Float32Array(TUBE_SIDES);
299	  for (let i = 0; i < TUBE_SIDES; i++) {
300	    ringCos[i] = Math.cos((i / TUBE_SIDES) * Math.PI * 2);
301	    ringSin[i] = Math.sin((i / TUBE_SIDES) * Math.PI * 2);
302	  }
303	  const halfW = BEAD_WIDTH_MM / 2;
304	  const col = new BABYLON.Color4();
305	  // Dernière tangente valide : reprise pour les échantillons confondus (mouvement d'extrusion
306	  // seule, sans déplacement), dont la tangente locale est nulle.
307	  let tx = 1, ty = 0, tz = 0;
308	  let idx = 0;
309	
310	  for (let j = 0; j < count; j++) {
311	    const p = j * 3;
312	    const hasPrev = !stripStart[j];
313	    const hasNext = j + 1 < count && !stripStart[j + 1];
314	    const from = hasPrev ? p - 3 : p;
315	    const to = hasNext ? p + 3 : p;
316	    let dx = centers[to] - centers[from];
317	    let dy = centers[to + 1] - centers[from + 1];
318	    let dz = centers[to + 2] - centers[from + 2];
319	    let len = Math.hypot(dx, dy, dz);
320	    if (len > 1e-6) {
321	      tx = dx / len; ty = dy / len; tz = dz / len;
322	    }
323	
324	    // Axe de buse rendu orthogonal à la tangente ; s'il lui est parallèle (déplacement le long
325	    // de la buse), n'importe quelle perpendiculaire convient.
326	    let ux = axes[p], uy = axes[p + 1], uz = axes[p + 2];
327	    const dot = ux * tx + uy * ty + uz * tz;
328	    ux -= dot * tx; uy -= dot * ty; uz -= dot * tz;
329	    len = Math.hypot(ux, uy, uz);
330	    if (len < 1e-6) {
331	      ux = -ty; uy = tx; uz = 0;
332	      len = Math.hypot(ux, uy, uz);
333	      if (len < 1e-6) { ux = 0; uy = -tz; uz = ty; len = Math.hypot(uy, uz); }
334	    }
335	    ux /= len; uy /= len; uz /= len;
336	    // Côté = tangente × axe.
337	    dx = ty * uz - tz * uy;
338	    dy = tz * ux - tx * uz;
339	    dz = tx * uy - ty * ux;
340	
341	    colorAt(centers[p + 1] + halfH, col);
342	    for (let i = 0; i < TUBE_SIDES; i++) {
343	      const v = j * TUBE_SIDES + i;
344	      const cs = ringCos[i], sn = ringSin[i];
345	      positions[v * 3] = centers[p] + dx * halfW * cs + ux * halfH * sn;
346	      positions[v * 3 + 1] = centers[p + 1] + dy * halfW * cs + uy * halfH * sn;
347	      positions[v * 3 + 2] = centers[p + 2] + dz * halfW * cs + uz * halfH * sn;
348	      // Normale d'ellipse : gradient (cos/a, sin/b) dans le repère (côté, axe).
349	      let nx = dx * cs / halfW + ux * sn / halfH;
350	      let ny = dy * cs / halfW + uy * sn / halfH;
351	      let nz = dz * cs / halfW + uz * sn / halfH;
352	      const nl = Math.hypot(nx, ny, nz) || 1;
353	      nx /= nl; ny /= nl; nz /= nl;
354	      normals[v * 3] = nx;
355	      normals[v * 3 + 1] = ny;
356	      normals[v * 3 + 2] = nz;
357	      colors[v * 4] = col.r;
358	      colors[v * 4 + 1] = col.g;
359	      colors[v * 4 + 2] = col.b;
360	      colors[v * 4 + 3] = 1;
361	    }
362	
363	    if (hasPrev) {
364	      const a0 = (j - 1) * TUBE_SIDES;
365	      const b0 = j * TUBE_SIDES;
366	      for (let i = 0; i < TUBE_SIDES; i++) {
367	        const i1 = (i + 1) % TUBE_SIDES;
368	        indices[idx++] = a0 + i;
369	        indices[idx++] = b0 + i;
370	        indices[idx++] = a0 + i1;
371	        indices[idx++] = a0 + i1;
372	        indices[idx++] = b0 + i;
373	        indices[idx++] = b0 + i1;
374	      }
375	      cumIndices[owner[j]] = idx;
376	    }
377	  }
378	  // Mouvements sans sous-segment propre (trajets à vide) : même compte que le précédent.
379	  for (let k = 1; k < moves.length; k++) {
380	    if (cumIndices[k] < cumIndices[k - 1]) cumIndices[k] = cumIndices[k - 1];
381	  }
382	
383	  const mesh = new BABYLON.Mesh(name, scene);
384	  const data = new BABYLON.VertexData();
385	  data.positions = positions;
386	  data.normals = normals;
387	  data.colors = colors;
388	  data.indices = indices.subarray(0, idx);
389	  data.applyToMesh(mesh);
390	  mesh.material = material;
391	  finalizePathMesh(mesh);
392	  return { mesh, cumIndices, indicesPerStep };
393	}
394	
395	/** Construit un LinesMesh (repère plateau) contenant tous les mouvements dont `extruding`
396	 * vaut `wantExtruding`, dans l'ordre du fichier. N'importe quel préfixe de la trajectoire
397	 * s'affiche ensuite en changeant simplement `indexCount`, sans reconstruire la géométrie. */
398	function buildPathMesh(
399	  name: string,
400	  parsed: ParsedGCode,
401	  segments: Uint32Array,
402	  wantExtruding: boolean,
403	  colorAt: (z: number, out: BABYLON.Color4) => void,
404	  scene: BABYLON.Scene,
405	): PathMesh {
406	  const { moves } = parsed;
407	  let vertexTotal = 0;
408	  for (let k = 1; k < moves.length; k++) {
409	    if (moves[k].extruding === wantExtruding) vertexTotal += segments[k] + 1;
410	  }
411	
412	  const cumIndices = new Uint32Array(moves.length);
413	  if (vertexTotal === 0) return { mesh: null, cumIndices, indicesPerStep: 2 };
414	
415	  const positions = new Float32Array(vertexTotal * 3);
416	  const colors = new Float32Array(vertexTotal * 4);
417	  const indices = new Uint32Array((vertexTotal - 1) * 2);
418	  const col = new BABYLON.Color4();
419	  const tip = { r: 0, z: 0 };
420	  let v = 0;
421	  let idx = 0;
422	
423	  for (let k = 1; k < moves.length; k++) {
424	    const cur = moves[k];
425	    if (cur.extruding === wantExtruding) {
426	      const prev = moves[k - 1];
427	      const n = segments[k];
428	      for (let s = 0; s <= n; s++) {
429	        const f = s / n;
430	        const c = (prev.c + (cur.c - prev.c) * f) * DEG2RAD;
431	        // Interpolation en coordonnées pivot (comme le firmware), puis conversion à la buse.
432	        nozzleTip(
433	          prev.r + (cur.r - prev.r) * f,
434	          prev.z + (cur.z - prev.z) * f,
435	          (prev.b + (cur.b - prev.b) * f) * DEG2RAD,
436	          tip,
437	        );
438	        positions[v * 3] = tip.r * Math.cos(c);
439	        positions[v * 3 + 1] = tip.z;
440	        positions[v * 3 + 2] = tip.r * Math.sin(c);
441	        colorAt(tip.z, col);
442	        colors[v * 4] = col.r;
443	        colors[v * 4 + 1] = col.g;
444	        colors[v * 4 + 2] = col.b;
445	        colors[v * 4 + 3] = col.a;
446	        if (s > 0) {
447	          indices[idx++] = v - 1;
448	          indices[idx++] = v;
449	        }
450	        v++;
451	      }
452	    }
453	    cumIndices[k] = idx;
454	  }
455	
456	  const mesh = new BABYLON.LinesMesh(name, scene, null, null, undefined, true, true);
457	  const data = new BABYLON.VertexData();
458	  data.positions = positions;
459	  data.colors = colors;
460	  data.indices = indices.subarray(0, idx);
461	  data.applyToMesh(mesh);
462	  finalizePathMesh(mesh);
463	  return { mesh, cumIndices, indicesPerStep: 2 };
464	}
465	
466	export interface GCodeLayer {
467	  load(parsed: ParsedGCode): void;
468	  /** Position de lecture, en index de mouvement fractionnaire. */
469	  setTime(t: number): void;
470	  setShowTravel(show: boolean): void;
471	  /** Tête complète (défaut) ou buse seule — masque tous les maillages de la tête sauf ceux nommés
472	   * « NOZZLE » (cf. `apex-gcode-show-full-head`). */
473	  setFullHead(show: boolean): void;
474	  setEnabled(enabled: boolean): void;
475	  /** Rotation courante du plateau autour de Y (radians, repère Babylon), 0 sans G-code. */
476	  getPlateRotation(): number;
477	  dispose(): void;
478	}
479	
480	/** Préfixe de nom de tous les maillages du calque (cf. exclusion de la capture du flou). */
481	export const GCODE_MESH_PREFIX = 'gcode';
482	
483	/** Le glTF est en mètres, la scène en millimètres. */
484	const GLTF_TO_MM = 1000;
485	/** Rotation du modèle de tête autour de l'axe de sa buse (radians) : tel qu'exporté, son axe de
486	 * basculement B est perpendiculaire à celui de la machine (Z du repère tête, la tête penchant
487	 * dans le plan radial XY). */
488	const HEAD_MODEL_YAW = Math.PI / 2;
489	
490	
491	/**
492	 * Charge le modèle de la tête (aetheris-4.glb) sous `headNode`, pointe de buse à l'origine du
493	 * noeud et corps vers +Y local. Le fichier est déjà posé debout sur la buse, mais le centre de
494	 * la face de sortie de la buse (maillage « NOZZLE origin ») est légèrement décalé de son
495	 * origine : on recale le modèle sur ce point plutôt que de faire confiance à l'origine.
496	 * Chargé dans un conteneur et renommé AVANT l'ajout à la scène : Viewport3D trie les maillages
497	 * par nom dès leur arrivée (capture du flou, sélection de modèles) et doit ignorer ceux du calque.
498	 */
499	async function loadHeadModel(scene: BABYLON.Scene, headNode: BABYLON.TransformNode, isDisposed: () => boolean) {
500	  const container = await BABYLON.SceneLoader.LoadAssetContainerAsync('', headModelUrl, scene, null, '.glb');
501	  if (isDisposed()) {
502	    container.dispose();
503	    return { loaded: false as const };
504	  }
505	  // Repérés AVANT le renommage ci-dessous (sur le nom d'origine du glTF, jamais reconstruit à
506	  // partir du nom préfixé/modifié) et renvoyés tels quels à l'appelant (cf. `setFullHead`) : plus
507	  // sûr qu'un `.includes('NOZZLE')` a posteriori sur des noms qui ont pu être transformés.
508	  const nozzleMeshes = container.meshes.filter((m) => m.name.includes('NOZZLE'));
509	  const prefix = `${GCODE_MESH_PREFIX}HeadModel_`;
510	  for (const mesh of container.meshes) {
511	    mesh.name = prefix + mesh.name;
512	    mesh.isPickable = false;
513	  }
514	  for (const node of container.transformNodes) node.name = prefix + node.name;
515	
516	  const model = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}HeadModel`, scene);
517	  model.scaling.setAll(GLTF_TO_MM);
518	  for (const node of container.rootNodes) node.parent = model;
519	
520	  // Pointe de buse mesurée avec le modèle seul (non encore rattaché à la tête) : son repère
521	  // monde n'est alors que l'échelle, donc la boîte monde est directement en repère tête.
522	  const nozzle = container.meshes.find((m) => m.name.includes('NOZZLE origin'));
523	  if (nozzle) {
524	    const chain: BABYLON.Node[] = [];
525	    for (let n: BABYLON.Node | null = nozzle; n; n = n.parent) chain.unshift(n);
526	    for (const n of chain) (n as BABYLON.TransformNode).computeWorldMatrix(true);
527	    const { minimumWorld: min, maximumWorld: max } = nozzle.getBoundingInfo().boundingBox;
528	    model.position.set(-(min.x + max.x) / 2, -min.y, -(min.z + max.z) / 2);
529	  }
530	  // Rotation portée par un noeud intermédiaire, APRÈS le recalage : elle tourne autour de l'axe
531	  // vertical passant par la pointe de buse, qui reste donc à l'origine.
532	  const mount = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}HeadModelMount`, scene);
533	  mount.rotation.y = HEAD_MODEL_YAW;
534	  mount.parent = headNode;
535	  model.parent = mount;
536	  container.addAllToScene();
537	  return { loaded: true as const, nozzleMeshes };
538	}
539	
540	/**
541	 * Calque de prévisualisation G-code posé dans une scène existante. `parent` est le repère du
542	 * plateau (origine au centre de sa surface) : Z = 0 du G-code y correspond.
543	 */
544	export function createGCodeLayer(
545	  scene: BABYLON.Scene,
546	  parent: BABYLON.TransformNode,
547	  /** Appelé à chaque mise à jour de la rotation du plateau (radians), pour y caler du décor. */
548	  onPlateRotation?: (rotationY: number) => void,
549	): GCodeLayer {
550	  const root = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Root`, scene);
551	  root.parent = parent;
552	  root.setEnabled(false);
553	
554	  // Repère tournant du plateau : toute la matière déposée en est enfant.
555	  const plateNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Plate`, scene);
556	  plateNode.parent = root;
557	
558	  // Tête : pointe de buse à l'origine du noeud, corps qui monte le long de +Y local ; le noeud
559	  // est ensuite orienté pour que ce corps penche de B vers +R. Primitives provisoires, remplacées
560	  // par le vrai modèle (loadHeadModel) une fois chargé ; gardées en repli s'il échoue.
561	  const headNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Head`, scene);
562	  headNode.parent = root;
563	  headNode.rotationQuaternion = BABYLON.Quaternion.Identity();
564	
565	  // Tête complète ou buse seule (cf. `setFullHead`) : simple bascule de visibilité par maillage,
566	  // « NOZZLE » (nom du modèle réel, cf. loadHeadModel) faisant office de repère — pas de plan de
567	  // coupe : plus simple, et jamais de coquille ouverte à boucher puisque chaque maillage garde ses
568	  // propres faces fermées, jamais tronquées à mi-hauteur.
569	  let fullHead = true;
570	
571	  const nozzleMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}NozzleMat`, scene);
572	  nozzleMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
573	  nozzleMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
574	  const nozzle = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}Nozzle`, { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
575	  nozzle.position.y = 4.5;
576	  nozzle.material = nozzleMat;
577	  nozzle.parent = headNode;
578	  const bodyMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadBodyMat`, scene);
579	  bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
580	  bodyMat.alpha = 0.55;
581	  const body = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}HeadBody`, { diameter: 14, height: 26, tessellation: 24 }, scene);
582	  body.position.y = 9 + 13;
583	  body.material = bodyMat;
584	  body.parent = headNode;
585	  nozzle.isPickable = false;
586	  body.isPickable = false;
587	  // `body` (le corps de la tête) n'a pas de contrepartie « NOZZLE » : c'est lui qu'il faut masquer
588	  // quand `fullHead` est faux, `nozzle` restant visible dans les deux cas (repli du modèle glTF,
589	  // où seuls les maillages nommés NOZZLE restent visibles — cf. le `.then` ci-dessous).
590	  body.setEnabled(fullHead);
591	  headNode.setEnabled(false);
592	
593	  // Tête complète ou buse seule (cf. `setFullHead`), applicable aux deux états possibles de la
594	  // tête : primitives de repli (nozzle/body, avant chargement du modèle ou s'il échoue) ou vrai
595	  // modèle glTF (après, cf. le `.then` ci-dessous) — jamais les deux en même temps, l'un dispose
596	  // l'autre. Sur le modèle réel, seuls les maillages de `headModelNozzleMeshes` (repérés une fois
597	  // pour toutes à leur chargement par `loadHeadModel`, cf. plus bas — jamais reconstruits ici par
598	  // un `.includes('NOZZLE')` sur un nom déjà transformé) restent visibles ; le reste (corps,
599	  // radiateur, ventilateur, connecteurs…) est simplement désactivé — jamais de plan de coupe ni de
600	  // bouchon à poser, chaque maillage garde ses propres faces, déjà fermées, intactes.
601	  let headModelNozzleMeshes: BABYLON.AbstractMesh[] | null = null;
602	  const applyHeadVisibility = () => {
603	    if (!headModelNozzleMeshes) {
604	      // Modèle glTF pas encore chargé (ou échec) : seules les primitives de repli existent.
605	      if (!body.isDisposed()) body.setEnabled(fullHead);
606	      return;
607	    }
608	    const nozzleSet = new Set<BABYLON.Node>(headModelNozzleMeshes);
609	    // `isEnabled()` d'un maillage suit toute sa chaîne d'ancêtres (cf. Node.isEnabled) : le loader
610	    // glTF parente souvent tout sous un noeud technique (`__root__`) — le désactiver, lui, masque
611	    // aussi ses enfants NOZZLE bien que LEUR propre drapeau reste actif. Jamais désactiver un
612	    // ancêtre d'un maillage NOZZLE, donc, seulement les branches qui n'en contiennent aucun.
613	    const ancestorsOfNozzle = new Set<BABYLON.Node>();
614	    for (const nozzleMesh of headModelNozzleMeshes) {
615	      for (let n: BABYLON.Node | null = nozzleMesh.parent; n && n !== headNode; n = n.parent) ancestorsOfNozzle.add(n);
616	    }
617	    for (const mesh of headNode.getChildMeshes()) {
618	      if (!nozzleSet.has(mesh) && !ancestorsOfNozzle.has(mesh)) mesh.setEnabled(fullHead);
619	    }
620	  };
621	
622	  let disposed = false;
623	  loadHeadModel(scene, headNode, () => disposed)
624	    .then((result) => {
625	      if (!result.loaded) return;
626	      nozzle.dispose(false, true);
627	      body.dispose(false, true);
628	      headModelNozzleMeshes = result.nozzleMeshes;
629	      applyHeadVisibility();
630	    })
631	    .catch((err) => console.warn('Modèle de tête G-code non chargé, primitives conservées :', err));
632	
633	  // Cordon : teinte portée par les couleurs de sommets (dégradé en hauteur), le matériau n'apporte
634	  // que l'éclairage. Faces arrière dessinées pour ne pas dépendre du sens des triangles, les
635	  // normales explicites (vers l'extérieur) donnant l'éclairage.
636	  const beadMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}BeadMat`, scene);
637	  beadMat.diffuseColor = new BABYLON.Color3(1, 1, 1);
638	  beadMat.specularColor = new BABYLON.Color3(0.25, 0.25, 0.25);
639	  beadMat.specularPower = 48;
640	  beadMat.emissiveColor = new BABYLON.Color3(0.08, 0.1, 0.14);
641	  beadMat.backFaceCulling = false;
642	
643	  let parsed: ParsedGCode | null = null;
644	  let segments = new Uint32Array(0);
645	  let extruded: PathMesh | null = null;
646	  let travel: PathMesh | null = null;
647	  let time = 0;
648	  let showTravel = false;
649	
650	  const up = BABYLON.Vector3.Up();
651	  const headDir = new BABYLON.Vector3();
652	  const headTip = { r: 0, z: 0 };
653	
654	  const apply = () => {
655	    if (!parsed || parsed.moves.length === 0) return;
656	    const last = parsed.moves.length - 1;
657	    const t = Math.max(0, Math.min(last, time));
658	    const state = stateAt(parsed.moves, t);
659	
660	    // Dans le repère main gauche de Babylon, rotation.y = ψ envoie un angle local θ
661	    // (x = cos θ, z = sin θ) sur θ − ψ. Avec ψ = C courant, un point déposé à C_dépôt est à
662	    // l'angle machine C_dépôt − C : pile sous la tête (angle 0) au moment de son dépôt, puis
663	    // entraîné avec le plateau. Le signe opposé ferait apparaître la pièce en miroir.
664	    plateNode.rotation.y = state.c * DEG2RAD;
665	    onPlateRotation?.(plateNode.rotation.y);
666	
667	    const bRad = state.b * DEG2RAD;
668	    nozzleTip(state.r, state.z, bRad, headTip);
669	    headNode.position.set(headTip.r, headTip.z, 0);
670	    // headDir.x positif = tête penchée vers +X, donc vers +R (à l'opposé de l'axe de rotation,
671	    // situé en X=0) puisque le nœud de tête est lui-même posé en X=+R. Signe vérifié visuellement
672	    // contre le comportement réel de la machine (le signe opposé penchait la tête vers l'axe).
673	    headDir.set(Math.sin(bRad), Math.cos(bRad), 0);
674	    BABYLON.Quaternion.FromUnitVectorsToRef(up, headDir, headNode.rotationQuaternion!);
675	
676	    // Préfixe affiché : mouvements terminés + fraction du mouvement en cours, au sous-segment
677	    // près (cohérent avec l'interpolation en C). Chaque mouvement a `segments[k]` sous-segments
678	    // dans son maillage, lignes comme cordon.
679	    const i = Math.floor(t);
680	    const next = Math.min(last, i + 1);
681	    const partialSteps = next > i ? Math.floor((t - i) * segments[next]) : 0;
682	    for (const [entry, wantExtruding] of [[extruded, true], [travel, false]] as const) {
683	      if (!entry?.mesh) continue;
684	      let count = entry.cumIndices[i];
685	      if (next > i && parsed.moves[next].extruding === wantExtruding) count += partialSteps * entry.indicesPerStep;
686	      const sub = entry.mesh.subMeshes?.[0];
687	      if (sub) sub.indexCount = count;
688	      entry.mesh.isVisible = count > 0;
689	    }
690	  };
691	
692	  const disposePaths = () => {
693	    extruded?.mesh?.dispose();
694	    travel?.mesh?.dispose();
695	    extruded = null;
696	    travel = null;
697	  };
698	
699	  return {
700	    load(next) {
701	      disposePaths();
702	      parsed = next;
703	      segments = new Uint32Array(next.moves.length);
704	      for (let k = 1; k < next.moves.length; k++) {
705	        const dc = Math.abs(next.moves[k].c - next.moves[k - 1].c);
706	        segments[k] = Math.max(1, Math.ceil(dc / MAX_SUBSEGMENT_DEG));
707	      }
708	
709	      // Dégradé en hauteur dans les teintes cyan de l'interface.
710	      const zSpan = Math.max(1e-6, next.maxZ - next.minZ);
711	      const low = new BABYLON.Color3(0.1, 0.45, 1);
712	      const high = new BABYLON.Color3(0.3, 0.95, 1);
713	      const extrudedColor = (z: number, out: BABYLON.Color4) => {
714	        const f = (z - next.minZ) / zSpan;
715	        out.set(low.r + (high.r - low.r) * f, low.g + (high.g - low.g) * f, low.b + (high.b - low.b) * f, 1);
716	      };
717	      const travelColor = (_z: number, out: BABYLON.Color4) => { out.set(0.8, 0.8, 0.85, 0.35); };
718	
719	      extruded = buildBeadMesh(`${GCODE_MESH_PREFIX}Extruded`, next, segments, extrudedColor, beadMat, scene);
720	      travel = buildPathMesh(`${GCODE_MESH_PREFIX}Travel`, next, segments, false, travelColor, scene);
721	      if (extruded.mesh) extruded.mesh.parent = plateNode;
722	      if (travel.mesh) {
723	        travel.mesh.parent = plateNode;
724	        travel.mesh.setEnabled(showTravel);
725	      }
726	
727	      headNode.setEnabled(next.moves.length > 0);
728	      time = next.moves.length - 1;
729	      apply();
730	    },
731	    setTime(t) {
732	      time = t;
733	      apply();
734	    },
735	    setShowTravel(show) {
736	      showTravel = show;
737	      travel?.mesh?.setEnabled(show);
738	    },
739	    setFullHead(show) {
740	      fullHead = show;
741	      applyHeadVisibility();
742	    },
743	    setEnabled(enabled) {
744	      root.setEnabled(enabled);
745	    },
746	    getPlateRotation() {
747	      return plateNode.rotation.y;
748	    },
749	    dispose() {
750	      disposed = true;
751	      disposePaths();
752	      root.dispose(false, true);
753	    },
754	  };
755	}
