.container {
  position: fixed;
  bottom: 24px;
  right: 24px;
  display: flex;
  align-items: center;
  z-index: 1000;
  pointer-events: none;
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);

  background: rgba(10, 15, 26, 0.25);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  padding: 8px 16px;
  border-radius: 16px;
  width: 293px;
}

.button {
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  width: 100%;
}

.sliceButton {
  background: rgba(0, 240, 255, 0.12);
  color: #00f0ff;
  padding: 10px 16px;
  border-radius: 12px;
  border: none;
  width: 100%;
  justify-content: center;

  &:hover:not(:disabled) {
    background: rgba(0, 240, 255, 0.22) !important;
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }

  &.disabledButton {
    background: rgba(255, 255, 255, 0.04);
    color: rgba(255, 255, 255, 0.25);
    cursor: not-allowed;
    box-shadow: none;
  }
}

