1	"use client";
2	
3	import React, { useEffect, useRef, useState } from 'react';
4	import { Sidebar } from '@/components/Sidebar';
5	import { FileSidebar } from '@/components/FileSidebar';
6	import { SliceSidebar } from '@/components/SliceSidebar';
7	import { CategoriesSidebar } from '@/components/CategoriesSidebar';
8	import { PrinterConfigSidebar } from '@/components/PrinterConfigSidebar';
9	import { AxisSidebar } from '@/components/AxisSidebar';
10	import { ModelingSidebar } from '@/components/ModelingSidebar';
11	import { TopRightMenu } from '@/components/TopRightMenu';
12	import { ModelStatusBox } from '@/components/ModelStatusBox';
13	import { ModelHoverTooltip } from '@/components/ModelHoverTooltip';
14	import { TextureEditorModal } from '@/components/TextureEditorModal';
15	import { SliceModal } from '@/components/SliceModal';
16	import { SlicingProgressModal } from '@/components/SlicingProgressModal';
17	import { ViewCube } from '@/components/ViewCube';
18	import { Viewport3D } from '@/components/Viewport3D';
19	import { SpaceTransitionOverlay } from '@/components/SpaceTransitionOverlay';
20	import { GCodePreview } from '@/components/GCodePreview';
21	import { GCodePreviewBar } from '@/components/GCodePreviewBar';
22	import { GCodeSpeedSelector } from '@/components/GCodeSpeedSelector';
23	import { useGCodePreview } from '@/hooks/use-gcode-preview';
24	import { useAnimate } from 'framer-motion';
25	import { Box } from 'lucide-react';
26	import { showSuccess } from '@/utils/toast';
27	
28	interface ModelStatus {
29	  name: string;
30	  dimensions: { x: number; y: number; z: number } | null;
31	}
32	
33	const Index = () => {
34	  const [activeTab, setActiveTab] = useState<'3d-view' | 'settings' | 'developer'>('3d-view');
35	  const [activeCategory, setActiveCategory] = useState<string | null>(null);
36	  const [isPrinterConfigOpen, setIsPrinterConfigOpen] = useState(false);
37	  const [selectedPrinter, setSelectedPrinter] = useState('Prusa MK4');
38	  const [selectedFilament, setSelectedFilament] = useState('PLA Premium (eSUN / Prusament)');
39	  const [isSliceModalOpen, setIsSliceModalOpen] = useState(false);
40	  const [isSlicingProgressOpen, setIsSlicingProgressOpen] = useState(false);
41	  const [modelStatus, setModelStatus] = useState<ModelStatus | null>(null);
42	  const [isPreviewActive, setIsPreviewActive] = useState(false);
43	  const isPreviewActiveRef = useRef(isPreviewActive);
44	  isPreviewActiveRef.current = isPreviewActive;
45	  // Logique de l'espace Prévisualisation (chargement/lecture G-code) : appelée ici (et non dans
46	  // GCodePreview) car sa barre de lecture (GCodePreviewBar) partage la rangée du bas avec la
47	  // pastille de statut du plateau, ce qui demande que les deux soient des enfants directs du même
48	  // conteneur flex plutôt que des composants positionnés indépendamment.
49	  const gcodePreview = useGCodePreview(isPreviewActive);
50	  // Le temps que ModelingSidebar déforme sa propre silhouette entre la forme de la pilule/des deux
51	  // panneaux de Prévisualisation et sa forme normale — cf. le commentaire sur `onTabChange` plus
52	  // bas et le prop `morph` de ModelingSidebar. `null` = pas de morph en cours ; sinon, `direction`
53	  // indique le sens ('enter' : la pilule/Prévisualisation devient le panneau Modélisation, 'exit' :
54	  // l'inverse) et `fromPreview` l'état de Prévisualisation à l'autre bout du morph (pilule ou
55	  // panneaux Preview) — figé à l'instant du clic, lu depuis isPreviewActiveRef, PAS depuis
56	  // isPreviewActive : Sidebar mute ce dernier dans le même geste, avant qu'on ait la chance de lire
57	  // sa valeur de départ. Contrairement à l'ancienne approche (deux calques à synchroniser — un
58	  // verre animé séparé, puis le vrai panneau), c'est ICI le même élément, déjà affiché avec son
59	  // contenu réel, qui change de forme : plus de raccord entre deux éléments distincts, donc plus
60	  // de risque de clignotement à la jonction.
61	  const [modelingMorph, setModelingMorph] = useState<{ direction: 'enter' | 'exit'; fromPreview: boolean } | null>(null);
62	  // Vrai dès le CLIC vers Modélisation (cf. l'écouteur d'apex-entering-modeling plus bas), jamais
63	  // seulement à `onCovered` (~900ms plus tard, une fois le rideau refermé) : le fondu-glissement du
64	  // panneau du bas de Prévisualisation doit être visible EN TRANSPARENCE À TRAVERS le rideau qui
65	  // monte, pas caché derrière lui — contrairement au vrai changement d'onglet (`onTabChange`), qui
66	  // lui reste cadencé par `onCovered`. Redevient faux une fois le morph 'enter' effectivement lancé
67	  // (le panneau du bas a alors largement eu le temps de finir sa disparition, 260ms contre les
68	  // ~900ms d'attente du rideau).
69	  const [leavingToModeling, setLeavingToModeling] = useState(false);
70	  const [statusBarRef, animateStatusBar] = useAnimate<HTMLDivElement>();
71	  const prevPreviewActiveRef = useRef(isPreviewActive);
72	
73	  // Au changement d'espace, la barre d'aide (TopRightMenu) passe par le coin bas gauche, là où
74	  // se trouve la barre de statut : celle-ci se rentre sous le bord de l'écran juste avant
75	  // (0,2 → 0,45 s ; la barre d'aide démarre à 0,495 s) et ressort une fois la barre d'aide
76	  // arrivée (1,1 s), pour ne pas se faire recouvrir.
77	  useEffect(() => {
78	    if (prevPreviewActiveRef.current === isPreviewActive) return;
79	    prevPreviewActiveRef.current = isPreviewActive;
80	    if (!statusBarRef.current) return;
81	    animateStatusBar(
82	      statusBarRef.current,
83	      { y: [0, 0, 80, 80, 0] },
84	      { duration: 1.4, times: [0, 0.2 / 1.4, 0.45 / 1.4, 1.1 / 1.4, 1], ease: [0.25, 1, 0.5, 1] },
85	    );
86	  }, [isPreviewActive, animateStatusBar, statusBarRef]);
87	
88	  /** L'onglet « Modélisation » de la Sidebar porte la valeur 'settings'. */
89	  const isModeling = activeTab === 'settings';
90	
91	  // Une fois CategoriesSidebar (et son panneau du bas) effectivement démontée par le passage en
92	  // Modélisation, `leavingToModeling` peut redescendre : il n'a plus d'effet visuel à cet instant
93	  // (le fondu est terminé depuis longtemps), mais doit être prêt (`false`) pour un futur cycle.
94	  useEffect(() => {
95	    if (isModeling) setLeavingToModeling(false);
96	  }, [isModeling]);
97	
98	  // Vrai du début d'un morph de sortie de Modélisation jusqu'au commit qui le termine, où
99	  // CategoriesSidebar est remontée et le lit (une seule fois, à son montage). Remis à `false` juste
100	  // après, une fois ce montage passé.
101	  const [arrivingFromModeling, setArrivingFromModeling] = useState(false);
102	  useEffect(() => {
103	    if (!modelingMorph) setArrivingFromModeling(false);
104	  }, [modelingMorph]);
105	
106	  React.useEffect(() => {
107	    const handleModelSelected = (event: CustomEvent<{
108	      name: string | null;
109	      dimensions?: { x: number; y: number; z: number };
110	    }>) => {
111	      if (!event.detail?.name) {
112	        setModelStatus(null);
113	        return;
114	      }
115	
116	      setModelStatus({
117	        name: event.detail.name,
118	        dimensions: event.detail.dimensions ?? null,
119	      });
120	    };
121	
122	    const handleModelImported = (event: CustomEvent<File>) => {
123	      if (event.detail?.name) {
124	        setModelStatus({ name: event.detail.name, dimensions: null });
125	      }
126	    };
127	
128	    const handlePreviewToggled = (event: CustomEvent<{ active: boolean }>) => {
129	      setIsPreviewActive(!!event.detail?.active);
130	    };
131	
132	    // Dispatché par Sidebar.tsx (handleTopTabClick) au tout début du clic vers Modélisation, avant
133	    // même que le rideau plein écran ne commence à monter — cf. le commentaire sur
134	    // `leavingToModeling` plus haut.
135	    const handleEnteringModeling = () => setLeavingToModeling(true);
136	
137	    window.addEventListener('apex-mesh-selected', handleModelSelected as EventListener);
138	    window.addEventListener('apex-import-model', handleModelImported as EventListener);
139	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
140	    window.addEventListener('apex-entering-modeling', handleEnteringModeling);
141	
142	    return () => {
143	      window.removeEventListener('apex-mesh-selected', handleModelSelected as EventListener);
144	      window.removeEventListener('apex-import-model', handleModelImported as EventListener);
145	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
146	      window.removeEventListener('apex-entering-modeling', handleEnteringModeling);
147	    };
148	  }, []);
149	
150	  const handleSlice = () => {
151	    window.dispatchEvent(new CustomEvent('apex-request-slice-models'));
152	    setIsSliceModalOpen(true);
153	  };
154	
155	  const handleConfirmSlice = () => {
156	    window.dispatchEvent(new CustomEvent('apex-slice-all-models'));
157	    setIsSliceModalOpen(false);
158	    setIsSlicingProgressOpen(true);
159	  };
160	
161	  const handleSlicingFinished = () => {
162	    setIsSlicingProgressOpen(false);
163	    showSuccess("Slicing plate completed successfully!");
164	  };
165	
166	  const handleOpenModel = () => {
167	    showSuccess("Select an STL or GLB file to add a model.");
168	  };
169	
170	  const handleSaveProject = () => {
171	    showSuccess("Project saved successfully.");
172	  };
173	
174	  return (
175	    <div
176	      className="flex flex-col h-screen w-screen overflow-hidden select-none relative"
177	      style={{ backgroundColor: '#2a2d34' }}
178	    >
179	      <FileSidebar 
180	        onOpenModel={handleOpenModel}
181	        onSaveProject={handleSaveProject}
182	        onOpenSettings={() => setActiveTab('settings')}
183	        onOpenPrinterConfig={() => {
184	          setIsPrinterConfigOpen(!isPrinterConfigOpen);
185	          setActiveCategory(null);
186	        }}
187	        selectedPrinter={selectedPrinter}
188	        selectedFilament={selectedFilament}
189	      />
190	
191	      <ModelStatusBox />
192	      <ModelHoverTooltip />
193	      <TextureEditorModal />
194	      <SliceModal
195	        isOpen={isSliceModalOpen}
196	        onClose={() => setIsSliceModalOpen(false)}
197	        onConfirm={handleConfirmSlice}
198	      />
199	      <SlicingProgressModal
200	        isOpen={isSlicingProgressOpen}
201	        onClose={() => setIsSlicingProgressOpen(false)}
202	        onFinished={handleSlicingFinished}
203	      />
204	
205	      <Sidebar
206	        activeTab={activeTab}
207	        onTabChange={(tab, toPreview) => {
208	          // Passage vers ou hors de Modélisation : le rideau plein écran (déjà déclenché par
209	          // Sidebar avant cet appel, cf. playSpaceTransition) masque le changement de `main`,
210	          // pendant lequel ModelingSidebar (montée en permanence tant que isModeling ||
211	          // modelingMorph) joue le morph — cf. son prop `morph`.
212	          if (tab === 'settings' && !isModeling) {
213	            // L'état de départ (Préparation ou Prévisualisation) est lu MAINTENANT depuis
214	            // isPreviewActiveRef, avant que Sidebar ne le fasse passer à jour dans ce même geste.
215	            // Les éléments sans place en Modélisation ont déjà disparu depuis le clic
216	            // (apex-entering-modeling, ~900ms plus tôt) : la déformation peut commencer tout de
217	            // suite, dans le même commit que la bascule CategoriesSidebar → ModelingSidebar.
218	            setModelingMorph({ direction: 'enter', fromPreview: isPreviewActiveRef.current });
219	          } else if (tab !== 'settings' && isModeling) {
220	            // Sortie de Modélisation : `tab === 'box'` que ce soit vers Préparation ou vers
221	            // Prévisualisation (cf. handleLayerClick dans Sidebar.tsx, branche `entering`, qui
222	            // passe `toPreview: true`) — la destination ne peut donc pas se lire depuis `tab` seul.
223	            setModelingMorph({ direction: 'exit', fromPreview: !!toPreview });
224	            setArrivingFromModeling(true);
225	          }
226	          setActiveTab(tab === 'box' ? '3d-view' : tab);
227	          setIsPrinterConfigOpen(false);
228	        }}
229	        onOpenModel={handleOpenModel}
230	      />
231	
232	      <TopRightMenu />
233	      <AxisSidebar />
234	      <ViewCube />
235	
236	      {/* Les panneaux slicer et le panneau modélisation s'excluent mutuellement. La bascule se fait
237	          TOUJOURS dans un seul commit, par un rendu conditionnel simple — jamais via
238	          AnimatePresence, qui retarde le démontage de l'ancien côté (et en mode 'wait', le
239	          montage du nouveau) d'au moins une tâche, donc d'au moins une frame peinte. Toute
240	          l'animation visible est portée ailleurs : la déformation par ModelingSidebar (prop
241	          `morph`), les fondus par `animate` dès le clic. */}
242	      {isModeling || modelingMorph?.direction === 'exit' ? (
243	        <ModelingSidebar
244	          morph={
245	            modelingMorph
246	              ? { ...modelingMorph, onDone: () => setModelingMorph(null) }
247	              : undefined
248	          }
249	        />
250	      ) : (
251	          <>
252	            <CategoriesSidebar
253	              activeCategory={activeCategory}
254	              onSelectCategory={(cat) => {
255	                setActiveCategory(cat);
256	                if (cat) setIsPrinterConfigOpen(false);
257	              }}
258	              // Remonté à la fin d'un morph de sortie de Modélisation : ce composant doit apparaître
259	              // directement dans la forme que ModelingSidebar vient de prendre (pilule ou panneaux
260	              // de Prévisualisation), sans rejouer d'entrée ni de mitose. Ces deux props ne sont lues
261	              // qu'au montage (figées en interne).
262	              initialPreviewActive={isPreviewActive}
263	              arrivingFromModeling={arrivingFromModeling}
264	              leavingToModeling={leavingToModeling}
265	              previewLowerContent={
266	                <GCodeSpeedSelector
267	                  speed={gcodePreview.speed}
268	                  setSpeed={gcodePreview.setSpeed}
269	                  showFullHead={gcodePreview.showFullHead}
270	                  setShowFullHead={gcodePreview.setShowFullHead}
271	                />
272	              }
273	            />
274	
275	            <PrinterConfigSidebar
276	              isOpen={isPrinterConfigOpen}
277	              onClose={() => setIsPrinterConfigOpen(false)}
278	              selectedPrinter={selectedPrinter}
279	              onSelectPrinter={setSelectedPrinter}
280	              selectedFilament={selectedFilament}
281	              onSelectFilament={setSelectedFilament}
282	            />
283	
284	            <SliceSidebar onSlice={handleSlice} />
285	          </>
286	      )}
287	
288	      <main className="flex-1 flex flex-col relative overflow-hidden z-10 bg-transparent">
289	        <div className="flex-1 w-full h-full">
290	          <Viewport3D />
291	        </div>
292	
293	        {/* Espace Prévisualisation : interface du prévisualisateur G-code polaire. Le tracé
294	            lui-même est rendu par Viewport3D, dans la même scène que la Préparation. Toujours
295	            monté pour conserver le fichier chargé d'un aller-retour à l'autre. */}
296	        <GCodePreview active={isPreviewActive} />
297	
298	        {/* À l'intérieur de `main` (donc borné à l'espace 3D) et sous les panneaux `position:
299	            fixed` (sidebars, menus, tooltips, z-index 1000+) : le flou et le voile ne doivent
300	            couvrir que le viewport, jamais les éléments en superposition. */}
301	        <SpaceTransitionOverlay />
302	
303	        {/* Bottom status / stats overlay — au-dessus du rideau de transition (z-index 30) pour
304	            ne pas être flouté, comme les panneaux fixes. Seule la pastille de statut (premier
305	            enfant, animé via statusBarRef) se rentre sous le bord de l'écran au changement
306	            d'espace : c'est elle qui se trouve dans le coin bas gauche où la barre d'aide vient se
307	            poser en Prévisualisation (cf. TopRightMenu). GCodePreviewBar, à droite, a sa PROPRE
308	            animation d'entrée/sortie (glissement depuis le bas) et ne doit donc PAS être montée à
309	            l'intérieur du conteneur animé par statusBarRef, sous peine d'hériter de son va-et-vient
310	            et de sembler apparaître puis disparaître avec la pastille dans une seule et même
311	            animation. */}
312	        <div className="absolute bottom-4 left-4 right-24 z-40 flex items-center justify-start gap-3 pointer-events-none">
313	          <div ref={statusBarRef} className="shrink-0">
314	            <div className="bg-[rgba(10,15,26,0.25)] backdrop-blur-[4px] -webkit-backdrop-blur-[4px] border-none rounded-lg px-3 py-2 text-xs text-zinc-300 flex items-center space-x-4 pointer-events-auto shadow-[0_8px_32px_0_rgba(0,0,0,0.4),0_2px_8px_0_rgba(0,0,0,0.3)]">
315	              {modelStatus ? (
316	                <>
317	                  <span className="flex items-center"><Box className="w-3.5 h-3.5 mr-1.5 text-blue-400" /> {modelStatus.name}</span>
318	                  {modelStatus.dimensions && (
319	                    <>
320	                      <span className="text-zinc-600">|</span>
321	                      <span>Dimensions: {modelStatus.dimensions.x.toFixed(1)} x {modelStatus.dimensions.z.toFixed(1)} x {modelStatus.dimensions.y.toFixed(1)} mm</span>
322	                    </>
323	                  )}
324	                  <span className="text-zinc-600">|</span>
325	                  <span className="text-emerald-400 font-medium">Ready to slice</span>
326	                </>
327	              ) : (
328	                <span className="text-zinc-400">Aucun modèle sur le plateau</span>
329	              )}
330	            </div>
331	          </div>
332	
333	          <GCodePreviewBar active={isPreviewActive} {...gcodePreview} />
334	        </div>
335	      </main>
336	    </div>
337	  );
338	};
