682	          />
683	          <motion.div
684	            className={clsx(styles.previewPanelLower, { [styles.morphing]: previewMorphPhase === 'reverse' })}
685	            initial={wasInitialPreviewActive ? { opacity: 0, x: -20 } : false}
686	            animate={{
