}

.categoryLabel {
  white-space: nowrap;
  font-size: 11px;
  font-weight: 600;
}

// Base commune des deux panneaux de Prévisualisation — même verre que .fusionMenuContainer
// ci-dessous et que le morphing qui les fait naître (LiquidGlassMorph), pour une bascule invisible.
// Géométrie alignée sur previewGeometry() dans CategoriesSidebar.tsx : départ au niveau de la
// pilule (top 212), fin à 236px du bas de l'écran.
%previewPanelBase {
  position: fixed;
  left: 24px;
  width: 344px;
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  border-radius: 20px;
  z-index: 1000;
  overflow: hidden;
  isolation: isolate;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    // 2,5× le verre standard (4px) — même valeur que PREVIEW_GLASS_BLUR_PX (LiquidGlassMorph.tsx),
    // flou de fin du morphing qui fait naître ces panneaux.
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }

  // Pendant la fusion inverse (retour vers Préparation, cf. previewMorphPhase dans
  // CategoriesSidebar.tsx), le verre animé (LiquidGlassMorph) tient lieu de fond : celui du
  // panneau disparaît instantanément, sans transition (sinon il se superposerait au verre animé).
  &.morphing {
    box-shadow: none;

    &::before {
      opacity: 0;
    }
  }
}

// Panneau du haut : ce que la pilule devient (contenu à brancher plus tard).
.previewPanelUpper {
  @extend %previewPanelBase;
  top: 212px;
  height: max(120px, 100vh - 714px);
}

// Panneau du bas, né par mitose du panneau du haut (contenu à brancher plus tard).
.previewPanelLower {
  @extend %previewPanelBase;
  top: calc(212px + max(120px, 100vh - 714px) + 16px);
  height: 250px;
}

// Bas du panneau du bas (sélecteur de vitesse, cf. `previewLowerContent`). S'estompe avec le
// fond pendant la fusion inverse, comme le contenu de la pilule (.morphing).
.previewPanelFooter {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  transition: opacity 0.2s ease;

  .morphing > & {
    opacity: 0;
  }
}

.fusionMenuContainer {
  position: fixed;
  left: 24px;
  top: 280px;
  width: 320px;
  max-height: 400px;
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  border-radius: 16px;
  z-index: 1001;
  display: flex;
  flex-direction: column;
  overflow: visible;

