1	import React, { useCallback, useLayoutEffect, useRef } from 'react';
2	import { motion, AnimatePresence } from 'framer-motion';
3	import { Play, Pause } from 'lucide-react';
4	import { type GCodeFileInfo } from '@/hooks/use-gcode-preview';
5	import styles from './GCodePreviewBar.module.scss';
6	
7	interface GCodePreviewBarProps {
8	  /** Espace Prévisualisation affiché. Nécessaire mais pas suffisant pour afficher la barre : elle
9	   * reste en plus masquée tant qu'aucun G-code n'est chargé ni en cours de chargement (cf.
10	   * `fileInfo`/`isLoading`). */
11	  active: boolean;
12	  fileInfo: GCodeFileInfo | null;
13	  isLoading: boolean;
14	  t: number;
15	  lastIndex: number;
16	  isPlaying: boolean;
17	  togglePlay: () => void;
18	  seek: (value: number) => void;
19	  speed: number;
20	  setSpeed: (speed: number) => void;
21	  showTravel: boolean;
22	  setShowTravel: (show: boolean) => void;
23	  openFilePicker: () => void;
24	}
25	
26	// `active` (isPreviewActive) devient vrai dans `onCovered` (cf. Sidebar.tsx), à l'instant précis
27	// où le rideau plein écran (SpaceTransitionOverlay) vient de finir de se peindre — PAS quand il a
28	// fini de se lever. À ce même instant démarrent aussi, tous masqués par le rideau : la mitose
29	// pilule → panneaux de CategoriesSidebar (PREVIEW_MORPH_MS = 1370ms) et le déplacement de la barre
30	// d'aide TopRightMenu (RESHAPE_DURATION = 1100ms) — les deux plus longues animations de la
31	// séquence. Le rideau lui-même reste peint (phase "text") 1000ms puis met 575ms à se lever
32	// (phase "fadeout", cf. getTextMs/FADEOUT_MS) : il ne révèle donc la scène qu'à 1575ms après
33	// `onCovered`, quand tout le reste est déjà terminé. Pour que cette barre apparaisse EN DERNIER
34	// dans la séquence perçue (au lieu d'être déjà là, toute faite, dès que le rideau se lève comme
35	// tout le reste), son glissement-fondu ne démarre qu'une fois le rideau entièrement levé.
36	const CURTAIN_REVEAL_MS = 1575;
37	
38	/**
39	 * Barre de lecture de l'espace Prévisualisation : play/pause, curseur de progression, vitesse,
40	 * affichage des trajets à vide et import de fichier. Toute la logique vient de
41	 * `useGCodePreview` (voir Index.tsx, qui possède le hook et transmet ses props ici).
42	 *
43	 * Pour l'instant seuls le bouton Play/Pause et le curseur de progression sont branchés ; le reste
44	 * des props (vitesse, trajets à vide, import) restent transmises sans être encore affichées, pour
45	 * ne pas avoir à retoucher Index.tsx quand ce contenu sera ajouté.
46	 *
47	 * N'apparaît que si un G-code est chargé ou en cours de chargement (`fileInfo`/`isLoading`) — pas
48	 * seulement parce que l'espace Prévisualisation est affiché : sans trajectoire à montrer, la barre
49	 * de lecture n'a rien à piloter et reste masquée comme le reste du contenu ci-dessus.
50	 *
51	 * Glissement-fondu depuis le bas de l'écran à l'entrée dans l'espace, et inverse à la sortie —
52	 * comme le panneau du bas de CategoriesSidebar (cf. FROM_PREVIEW_FADE_MS), mais vertical plutôt
53	 * qu'horizontal puisque cette barre vient du bord bas de l'écran plutôt que du bord gauche.
54	 * Retardée (CURTAIN_REVEAL_MS) pour apparaître en tout dernier, une fois le rideau levé et le
55	 * reste de la séquence terminé — jamais à la sortie de l'espace, où elle disparaît normalement.
56	 * Cette même transition sert aussi à l'apparition/disparition au chargement/déchargement d'un
57	 * G-code une fois l'espace déjà affiché, sans le délai CURTAIN_REVEAL_MS (non pertinent hors de
58	 * la séquence d'entrée dans l'espace, cf. `visible` ci-dessous).
59	 */
60	export const GCodePreviewBar: React.FC<GCodePreviewBarProps> = ({
61	  active,
62	  fileInfo,
63	  isLoading,
64	  t,
65	  lastIndex,
66	  isPlaying,
67	  togglePlay,
68	  seek,
69	}) => {
70	  const trackRef = useRef<HTMLDivElement>(null);
71	  const visible = active && (!!fileInfo || isLoading);
72	
73	  // CURTAIN_REVEAL_MS ne doit retarder que la toute première apparition de la barre après l'entrée
74	  // dans l'espace (rideau qui se lève) — pas une réapparition ultérieure au chargement d'un
75	  // G-code alors que l'espace est déjà affiché depuis longtemps, qui doit être immédiate.
76	  const revealDelayMs = useRef(CURTAIN_REVEAL_MS);
77	  useLayoutEffect(() => {
