const lineStats = emptyStats();
const tipA = { r: 0, z: 0 };
const tipB = { r: 0, z: 0 };
for (let k = 1; k < moves.length; k++) {
  const a = moves[k - 1];
  const m = moves[k];
  let dist: number;
  if (kind === 'polar') {
    nozzleTip(a.x, a.z, a.b * DEG2RAD, tipA);
    nozzleTip(m.x, m.z, m.b * DEG2RAD, tipB);
