let maxSpeed = Infinity;
let headerMaxSpeed = Infinity;

const handleComment = (comment: string) => {
  if (WIPE_START_RE.test(comment)) { inWipe = true; return; }
  if (WIPE_END_RE.test(comment)) { inWipe = false; return; }
  const header = HEADER_RE.exec(comment);
  if (header) {
    const key = header[1].toLowerCase();
    if (key === 'printable_area' || key === 'bed_shape') {
      bedCenter = shapeCenter(header[2]) ?? bedCenter;
    } else {
      const value = parseFloat(header[2]);
      if (value > 0) {
        if (key === 'filament_diameter') filamentDiameter = value;
        else if (key === 'filament_density') filamentDensity = value;
        else if (key === 'machine_max_speed_x') headerMaxSpeed = value;
        else firmwareRetract = value;
      }
    }
    return;
  }
  const feat = FEATURE_RE.exec(comment);
  if (feat && !comment.includes('=')) feature = resolveLineType(feat[1]);
};

