const { app, BrowserWindow, ipcMain, dialog } = require('electron');
const path = require('node:path');
const fs = require('node:fs');
const os = require('node:os');
const { spawn } = require('node:child_process');

const isDev = process.env.ELECTRON_START_URL !== undefined;

function createWindow() {
  const win = new BrowserWindow({
    width: 1440,
    height: 900,
    minWidth: 1024,
    minHeight: 640,
    backgroundColor: '#0a0f1a',
    autoHideMenuBar: true,
    webPreferences: {
      contextIsolation: true,
      nodeIntegration: false,
      preload: path.join(__dirname, 'preload.cjs'),
    },
  });

  if (isDev) {
    win.loadURL(process.env.ELECTRON_START_URL);
    win.webContents.openDevTools({ mode: 'detach' });
  } else {
    win.loadFile(path.join(__dirname, '../dist/index.html'));
  }
}

// ---------------------------------------------------------------------------------------------
// Conversion polaire (python/gcode_to_polar.py)
// ---------------------------------------------------------------------------------------------

/** Script de conversion : copié hors de l'archive asar à l'empaquetage (extraResources). */
function converterScript() {
  return app.isPackaged
    ? path.join(process.resourcesPath, 'python-scripts', 'gcode_to_polar.py')
    : path.join(__dirname, '..', 'python', 'gcode_to_polar.py');
}

/** Interpréteurs essayés dans l'ordre : Python embarqué (application empaquetée, ou téléchargé
 * dans build/python-embed en dev), puis Python du système. */
function pythonCandidates() {
  const embedded = app.isPackaged
    ? path.join(process.resourcesPath, 'python', 'python.exe')
    : path.join(__dirname, '..', 'build', 'python-embed', 'python.exe');
  const candidates = [];
  if (fs.existsSync(embedded)) candidates.push({ command: embedded, args: [] });
  if (process.platform === 'win32') candidates.push({ command: 'py', args: ['-3'] });
  candidates.push({ command: 'python3', args: [] }, { command: 'python', args: [] });
  return candidates;
}

/** Lance le script avec le premier interpréteur disponible ; `onStderrLine` reçoit chaque ligne
 * d'erreur standard (progression). */
function runPython(scriptArgs, onStderrLine) {
  const candidates = pythonCandidates();
  return new Promise((resolve, reject) => {
    const attempt = (index) => {
      if (index >= candidates.length) {
        reject(new Error('Aucun interpréteur Python disponible.'));
        return;
      }
      const { command, args } = candidates[index];
      const child = spawn(command, [...args, ...scriptArgs], { shell: false, windowsHide: true });
      let stdout = '';
      let stderrRest = '';
      const errors = [];
      child.stdout.on('data', (chunk) => { stdout += chunk; });
      child.stderr.on('data', (chunk) => {
        const lines = (stderrRest + chunk).split(/\r?\n/);
        stderrRest = lines.pop();
        for (const line of lines) {
          if (!onStderrLine(line)) errors.push(line);
        }
      });
      child.on('error', (err) => {
        if (err.code === 'ENOENT') attempt(index + 1);
        else reject(err);
      });
      child.on('close', (code) => {
        if (code === 0) resolve(stdout);
        // Lanceur Windows `py` présent mais sans Python 3 installé : essayer le suivant.
        else if (code === 103 || code === 9009) attempt(index + 1);
        else reject(new Error(errors.filter(Boolean).slice(-5).join('\n') || `Python a échoué (code ${code}).`));
      });
    };
    attempt(0);
  });
}

const CONVERSION_MODES = new Set(['polar', 'dynamic']);

ipcMain.handle('apex:convert-gcode', async (event, request) => {
  const { text, mode, centerX, centerY, source } = request ?? {};
  if (typeof text !== 'string' || !CONVERSION_MODES.has(mode) || !Number.isFinite(centerX) || !Number.isFinite(centerY)) {
    throw new Error('Requête de conversion invalide.');
  }
  const dir = await fs.promises.mkdtemp(path.join(os.tmpdir(), 'apex-convert-'));
  try {
    const input = path.join(dir, 'input.gcode');
    const output = path.join(dir, 'output.gcode');
    await fs.promises.writeFile(input, text, 'utf8');
    const stdout = await runPython(
      [
        converterScript(), input, output,
        '--mode', mode,
        '--center-x', String(centerX),
        '--center-y', String(centerY),
        '--source', typeof source === 'string' ? source.slice(0, 200) : '',
      ],
      (line) => {
        const match = /^PROGRESS (\d+)$/.exec(line);
        if (match && !event.sender.isDestroyed()) event.sender.send('apex:convert-progress', Number(match[1]));
        return !!match;
      },
    );
    let summary = null;
    try { summary = JSON.parse(stdout.trim().split(/\r?\n/).pop()); } catch { /* résumé facultatif */ }
    return { text: await fs.promises.readFile(output, 'utf8'), summary };
  } finally {
    fs.promises.rm(dir, { recursive: true, force: true }).catch(() => {});
  }
});

ipcMain.handle('apex:save-gcode', async (event, request) => {
  const { name, text } = request ?? {};
  if (typeof text !== 'string') throw new Error("Requête d'enregistrement invalide.");
  const { canceled, filePath } = await dialog.showSaveDialog(BrowserWindow.fromWebContents(event.sender), {
    title: 'Exporter le G-code',
    defaultPath: typeof name === 'string' && name ? path.basename(name) : 'apex.gcode',
    filters: [{ name: 'G-code', extensions: ['gcode', 'gco', 'g'] }],
  });
  if (canceled || !filePath) return { saved: false };
  await fs.promises.writeFile(filePath, text, 'utf8');
  return { saved: true, path: filePath };
});

app.whenReady().then(() => {
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

