// Carte de conversion, sous le panneau du bas de Prévisualisation (même verre que
// %previewPanelBase de CategoriesSidebar.module.scss) et au-dessus de la barre d'aide de
// TopRightMenu (bottom 72px, ~44px de haut) : ~86px de haut dans les 120px disponibles.
.card {
  position: fixed;
  left: 24px;
  width: 440px; // PREVIEW_W (spaceMorphGeometry.ts)
  top: calc(212px + max(120px, 100vh - 714px) + 16px + 250px + 16px);
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 16px;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  overflow: hidden;
  isolation: isolate;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

.message {
  display: flex;
  align-items: flex-start;
  gap: 8px;

  p {
    margin: 0;
    font-size: 11px;
    line-height: 15px;
    font-weight: 500;
    color: rgba(255, 255, 255, 0.85);
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
}

.icon {
  flex: 0 0 auto;
  margin-top: -1px;
}

.warning {
  color: #ffb547;
}

.success {
  color: #00f0ff;
}

.error {
  color: #ff5c5c;
}

.controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

// Même contrôle segmenté que GCodeSpeedSelector.
.segments {
  flex: 1 1 auto;
  display: flex;
  gap: 2px;
  padding: 3px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.05);
}

.segment {
  flex: 1 1 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 24px;
  border: none;
  outline: none;
  border-radius: 7px;
  background: transparent;
  color: rgba(255, 255, 255, 0.7);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover:not(:disabled) {
    color: rgba(255, 255, 255, 0.95);
    background: rgba(255, 255, 255, 0.12);
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }

  &:disabled {
    cursor: default;
  }

  &.active {
    background: rgba(0, 240, 255, 0.18);
    color: #00f0ff;
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }
}

.tag {
  font-size: 9px;
  font-weight: 600;
  padding: 1px 5px;
  border-radius: 5px;
  background: rgba(0, 240, 255, 0.12);
  color: rgba(0, 240, 255, 0.85);
}

// Même bouton que le bouton SLICE/EXPORT de SliceSidebar.
.convertButton {
  flex: 0 0 auto;
  min-width: 118px;
  height: 30px;
  padding: 0 14px;
  border: none;
  outline: none;
  border-radius: 10px;
  background: rgba(0, 240, 255, 0.12);
  color: #00f0ff;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover:not(:disabled) {
    background: rgba(0, 240, 255, 0.22);
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }

  &:disabled {
    background: rgba(255, 255, 255, 0.04);
    color: rgba(255, 255, 255, 0.35);
    cursor: default;
  }
}

.progress {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  background: #00f0ff;
  box-shadow: 0 0 8px rgba(0, 240, 255, 0.6);
  transition: width 0.15s linear;
}

