import { readFileSync } from 'node:fs';
import { parseGCode } from './bundle.mjs';
const S = 'C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/140664a4-b513-46ef-9738-2f24690c8ca1/scratchpad/';
