for (const b of ['AnySlicerNext', 'CreaPrint', 'IceSL']) {
  const src = parseGCode(readFileSync(`R:/APEX_NEW_VERSION/slicer_ux/research/gcode-samples/${b}.gcode`, 'utf8'));
